package com.efgenbosh.backend.dto.car;
import com.efgenbosh.backend.domain.RepairCase;
import java.time.OffsetDateTime;
public record RepairCaseRegistryResponse(Long id, Long carId, Long accountingNumber, String vehicleMake, String vehicleModel, String registrationNumber, String vin, String ownerName, String ownerPhone, String caseNumber, String repairType, String status, String claimNumber, Long insurerId, Long contractorId, int partsTotal, int partsReceived, OffsetDateTime createdAt, Long createdBy, OffsetDateTime updatedAt, Long updatedBy) {
    public static RepairCaseRegistryResponse from(RepairCase item, int partsTotal, int partsReceived) { var car = item.getCar(); var contractorId = item.getContractorId() != null ? item.getContractorId() : car.getContractorId(); return new RepairCaseRegistryResponse(item.getId(), car.getId(), car.getAccountingNumber(), car.getVehicleMake(), car.getVehicleModel(), car.getRegistrationNumber(), car.getVin(), car.getOwnerName(), car.getOwnerPhone(), item.getCaseNumber(), item.getRepairType(), item.getStatus(), item.getClaimNumber(), item.getInsurerId(), contractorId, partsTotal, partsReceived, item.getCreatedAt(), item.getCreatedBy(), item.getUpdatedAt(), item.getUpdatedBy()); }
}
